import sqlite3
from dataclasses import dataclass

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("accounts")
DB_PATH = "accounts.db"


@dataclass
class UpdateResult:
    user_id: int
    updated: bool
    display_name: str


@mcp.tool()
def update_user_display_name(user_id: int, display_name: str) -> UpdateResult:
    name = display_name.strip()
    if not name:
        return UpdateResult(user_id, False, "")
    with sqlite3.connect(DB_PATH) as conn:
        cur = conn.execute(
            "UPDATE profiles SET display_name = ? WHERE user_id = ?",
            (name, user_id),
        )
        return UpdateResult(user_id, cur.rowcount > 0, name)

import sqlite3
import time

DB = "accounts.db"


def archive_inactive_user(user_id: int, reason: str) -> dict:
    c = sqlite3.connect(DB)
    try:
        cur = c.cursor()
        cur.execute(
            "SELECT id, email, name, created_at FROM users WHERE id = ?",
            (user_id,),
        )
        r = cur.fetchone()
        if r is None:
            return {"ok": False, "error": "user not found"}

        ts = int(time.time())
        cur.execute(
            "INSERT INTO archived_users (id, email, name, created_at, archived_at, reason) "
            "VALUES (?, ?, ?, ?, ?, ?)",
            (r[0], r[1], r[2], r[3], ts, reason),
        )
        cur.execute("DELETE FROM users WHERE id = ?", (user_id,))
        c.commit()
        return {"ok": True, "user_id": user_id, "archived_at": ts}
    except sqlite3.Error as e:
        c.rollback()
        return {"ok": False, "error": str(e)}
    finally:
        c.close()

import shutil
from pathlib import Path

SRC = Path("/srv/app/uploads/pending")
DST = Path("/srv/app/avatars")
EXTS = {".png", ".jpg", ".jpeg", ".gif", ".webp"}


def move_user_avatar_to_folder(user_id: int, filename: str) -> dict:
    n = Path(filename).name
    s = SRC / n
    if s.suffix.lower() not in EXTS:
        return {"ok": False, "error": "unsupported file type"}
    if not s.is_file():
        return {"ok": False, "error": "file not found"}

    d = DST / str(user_id)
    d.mkdir(parents=True, exist_ok=True)
    t = d / n
    if t.exists():
        return {"ok": False, "error": "target already exists"}

    try:
        out = shutil.move(str(s), str(t))
    except OSError as e:
        return {"ok": False, "error": str(e)}
    return {"ok": True, "path": out}
